<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { api, displayDate } from '../api'
import Chart from '../components/Chart.vue'
import RoleCard from '../components/RoleCard.vue'
const instrument = ref(null), snapshot = ref(null), history = ref([]), profile = ref(null), answers = reactive({}), consent = ref(false), busy = ref(false), loading = ref(true), error = ref(''), message = ref('')
const withdrawalId = ref(null), submissionId = ref(null)
const statusNames = {insufficient_data:'回答尚不完整',exploring:'正在探索',multiple_interests:'多方向兴趣',highlighted_interest:'当前偏好'}
const dimensions = [{code:'R',label:'实干活动'},{code:'I',label:'研究活动'},{code:'A',label:'创作活动'},{code:'S',label:'助人活动'},{code:'E',label:'开拓活动'},{code:'C',label:'规范活动'}]
const options = [{value:1,label:'很不喜欢'},{value:2,label:'不太喜欢'},{value:3,label:'一般'},{value:4,label:'比较喜欢'},{value:5,label:'很喜欢'},{value:null,label:'不了解 / 暂不回答'}]
const groups = computed(()=>dimensions.map(d=>({...d,questions:instrument.value?.questions.filter(q=>q.dimension === d.code) || [],answered:instrument.value?.questions.filter(q=>q.dimension === d.code && typeof answers[q.id] === 'number').length || 0})))
const answered = computed(()=>Object.values(answers).filter(a=>typeof a === 'number').length)
const complete = computed(()=>groups.value.every(g=>g.answered >= 4))
const chartOption = computed(()=>({grid:{left:85,right:35,bottom:25,top:15},tooltip:{trigger:'axis',valueFormatter:v=>`${Math.round(v*100)} / 100`},xAxis:{type:'value',min:0,max:1,axisLabel:{formatter:v=>`${Math.round(v*100)}`},splitLine:{lineStyle:{color:'#edf0e9'}}},yAxis:{type:'category',data:dimensions.map(d=>d.label),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#647867'}},series:[{type:'bar',barWidth:23,data:dimensions.map(d=>snapshot.value?.scores?.[d.code] ?? null),itemStyle:{color:'#7b9c82',borderRadius:[0,5,5,0]},label:{show:true,position:'right',formatter:p=>`${Math.round(p.value*100)}`}}]}))
async function load(){ loading.value = true; error.value = ''; try { const [i,p,s,h] = await Promise.all([api('/interests/instrument'),api('/profile'),api('/profile/roles'),api('/interests/history')]); instrument.value=i; profile.value=p; snapshot.value=s; history.value=h; for(const q of i.questions) answers[q.id]=undefined }catch(e){error.value=e.message}finally{loading.value=false} }
async function submit(){busy.value=true;error.value='';message.value='';try {submissionId.value ||= crypto.randomUUID(); const payload={instrument_version:instrument.value.version,answers:Object.fromEntries(instrument.value.questions.map(q=>[q.id,answers[q.id] ?? null])),consent:consent.value,profile_version:profile.value?.version,submission_id:submissionId.value}; await api('/interests/responses',{method:'POST',body:payload}); [snapshot.value,history.value]=await Promise.all([api('/profile/roles'),api('/interests/history')]);submissionId.value=null;message.value=complete.value ? '兴趣结果与探索伙伴已保存。看看下一步可以尝试什么。' : '已保存本次回答，信息不足的维度不会自动判定角色。'; }catch(e){error.value=e.message}finally{busy.value=false} }
async function updateDisplay(body){busy.value=true;error.value='';try {snapshot.value=await api('/profile/roles/display',{method:'PATCH',body});message.value='已更新私人展示偏好，问卷原始得分保持不变。'}catch(e){error.value=e.message}finally{busy.value=false} }
async function withdraw(responseId){busy.value=true;error.value='';try {const deleted = await api(`/interests/responses/${responseId}`,{method:'DELETE'}); [snapshot.value,history.value]=await Promise.all([api('/profile/roles'),api('/interests/history')]);withdrawalId.value=null;message.value=deleted.message || `已撤回并删除这份私人问卷及角色计算记录，同时删除 ${deleted.deleted_decision_runs ?? 0} 份关联决策记录和行动进度。`}catch(e){error.value=e.message}finally{busy.value=false} }
watch(answers,()=>{submissionId.value=null},{deep:true})
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">MEET YOUR CAREER COMPANION</div><h1>让兴趣，有一个可爱的名字<span class="heading-dot">.</span></h1><p>认识你更愿意做的事情，用小行动探索职业方向。答案与结果默认仅本人可见。</p></div><RouterLink class="button" to="/decisions">带着画像去比较路径 ↗</RouterLink></div>
  <div v-if="error" class="alert error" role="alert">{{ error }}<button v-if="!instrument" class="ghost" @click="load">重新加载</button><p>若提示画像版本变化，请返回画像页确认并重新加载；问卷版本变化时需要使用当前题目。</p></div>
  <div v-if="message" class="alert success" role="status">{{ message }}</div><div v-if="loading" class="empty">正在加载兴趣问卷…</div>
  <div v-else-if="instrument" class="interest-layout">
    <form class="interest-form" @submit.prevent="submit">
      <section class="panel"><div class="panel-heading"><h2>职业活动兴趣 · {{ instrument.questions.length }} 题</h2><span class="tag">已回答 {{ answered }} / {{ instrument.questions.length }}</span></div><p class="muted">请依据当前兴趣选择，回答“不了解”也可以。每类至少回答 4 题、总计至少 24 题才自动给出角色建议。没有标准答案，也不代表你是否有能力完成任务。</p><p class="data-note">{{ instrument.notice }} · 问卷 {{ instrument.version }}</p><div class="question-progress"><span v-for="group in groups" :key="group.code" :class="{complete:group.answered >= 4}">{{ group.label }} {{ group.answered }}/{{ group.questions.length }}</span></div></section>
      <section v-for="group in groups" :key="group.code" class="panel question-group"><div class="panel-heading"><h2>{{ group.label }}</h2><span class="tag neutral">{{ group.answered }} / {{ group.questions.length }} 有效回答</span></div><fieldset v-for="question in group.questions" :key="question.id" class="question-item"><legend>{{ question.text }}</legend><div class="question-options"><label v-for="option in options" :key="option.label" class="choice" :class="{selected:answers[question.id] === option.value}"><input v-model="answers[question.id]" type="radio" :name="question.id" :value="option.value">{{ option.label }}</label></div></fieldset></section>
      <section class="panel"><label class="choice consent-choice"><input v-model="consent" type="checkbox" required>我自愿填写，并同意平台将回答用于本人的职业兴趣解释与探索建议。</label><p class="muted">自编活动兴趣题目用于探索，未声称具有标准化心理测量效度。</p><div v-if="!profile" class="alert demo">请先保存个人画像，再保存本次问卷。<RouterLink to="/profile">去填写画像 →</RouterLink></div><div class="actions"><button class="button" :disabled="busy || !consent || !profile">{{ busy ? '保存中…' : complete ? '生成我的探索伙伴 →' : '保存回答（暂不自动分类）' }}</button></div></section>
    </form>
    <aside class="interest-results"><RoleCard :snapshot="snapshot" :roles="instrument.roles" editable :busy="busy" @display="updateDisplay"/><section v-if="snapshot" class="panel"><div class="panel-heading"><h2>六维兴趣地图</h2><span class="tag">兴趣，不是能力</span></div><Chart :option="chartOption" label="职业活动兴趣六维条形图，0至100分；缺失值不绘制柱条"/><div class="interest-score-list"><div v-for="d in dimensions" :key="d.code"><span>{{ d.label }}</span><strong>{{ snapshot.scores?.[d.code] == null ? '回答不足' : `${Math.round(snapshot.scores[d.code]*100)} / 100` }}</strong></div></div><p class="data-note">同一次问卷中的活动偏好；空值为回答不足。不同方向可以同时很喜欢，分数不代表录用概率。</p></section><section class="panel"><h2>兴趣变化记录</h2><div v-if="!history.length" class="empty">你的第一份兴趣记录，从这里开始。</div><details v-for="h in history" :key="h.response_id || h.id" class="timeline-item"><summary>{{ displayDate(h.created_at) }} · 画像 V{{ h.profile_version }}</summary><p>规则 {{ h.rule_version }} · {{ statusNames[h.status] || h.status }}</p><p v-for="r in h.reasons || []" :key="r">{{ r }}</p><button v-if="withdrawalId !== h.response_id" class="ghost" :disabled="busy" @click="withdrawalId = h.response_id">撤回这份问卷</button><div v-else class="alert error"><p>这份问卷的原始回答与角色计算，以及引用它的本人决策记录和行动进度将一并删除，无法恢复。</p><div class="actions"><button class="ghost" :disabled="busy" @click="withdraw(h.response_id)">确认撤回</button><button class="ghost" :disabled="busy" @click="withdrawalId = null">保留记录</button></div></div></details></section></aside>
  </div>
</template>
